<template><div class="full-page login-bg"><div class="login-card"><div class="login-title">产品管理系统</div><div class="login-sub">企业内部产品目录 / 报价后台</div><el-form @keyup.enter="submit"><el-form-item><el-input v-model="form.username" placeholder="账号" size="large" clearable/></el-form-item><el-form-item><el-input v-model="form.password" type="password" show-password placeholder="密码" size="large"/></el-form-item><el-button type="primary" size="large" style="width:100%" :loading="loading" @click="submit">登录</el-button></el-form></div></div></template>
<script setup>import {reactive,ref} from 'vue';import {ElMessage} from 'element-plus';import {useRouter} from 'vue-router';import {useAuthStore} from '../stores/auth';const r=useRouter(),auth=useAuthStore(),loading=ref(false),form=reactive({username:'admin',password:'Admin@123456'});async function submit(){loading.value=true;try{await auth.login(form.username,form.password);r.push('/products')}catch(e){ElMessage.error(e.response?.data?.message||'登录失败')}finally{loading.value=false}}</script>
